css:
/* Sage / Forest & Porcelain — dark palette from core/ui MojaLossTheme.kt */

*{box-sizing:border-box;margin:0;padding:0}
html,body{width:1920px;height:1080px;overflow:hidden;background:#101B17;color:#EDF3EC;font-family:"SamsungOne","Roboto","Helvetica Neue",Arial,sans-serif;-webkit-font-smoothing:antialiased}
#backdrop{position:fixed;top:0;left:0;right:0;bottom:0;background:linear-gradient(135deg,#14271D,#101B17 40%,#182B22 70%,#102119);background-size:cover;background-position:center;overflow:hidden}
.bd-layer{position:absolute;top:0;left:0;right:0;bottom:0;background-size:cover;background-position:center;opacity:0;transform:scale(1.025);transition:opacity .48s cubic-bezier(.22,1,.36,1),transform .65s cubic-bezier(.22,1,.36,1);will-change:opacity,transform}
.bd-layer.on{opacity:1;transform:scale(1)}
@keyframes screenIn{0%{opacity:0;transform:translateY(10px)}100%{opacity:1;transform:translateY(0)}}
@keyframes textSwap{0%{opacity:.35;transform:translateY(4px)}100%{opacity:1;transform:translateY(0)}}
#root{position:relative;height:100%;padding:56px 96px;overflow:hidden}
#root.screen-enter>.rows,#root.screen-enter>.signin,#root.screen-enter>.state{animation:screenIn .28s cubic-bezier(.22,1,.36,1)}
.hero-swap{animation:textSwap .18s cubic-bezier(.22,1,.36,1)}
h1{font-size:56px;font-weight:700;letter-spacing:-.5px}h2{font-size:30px;font-weight:600;margin:0 0 18px;letter-spacing:-.2px}
.muted{color:#B7C9BD}.brand{display:flex;align-items:center;gap:16px;font-size:30px;font-weight:700;color:#B4D2BD}
.brand i{width:44px;height:44px;border-radius:14px;background:#B4D2BD;display:inline-block;box-shadow:inset 0 0 0 10px #254D3C}
.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:34px}
.glass{background:rgba(37,61,48,.94);border:1px solid rgba(180,210,189,.22);border-radius:22px;backdrop-filter:blur(24px);box-shadow:0 16px 40px rgba(0,0,0,.38)}
.focusable{outline:none;transition:transform .24s cubic-bezier(.22,1,.36,1),box-shadow .24s cubic-bezier(.22,1,.36,1),background-color .2s ease,border-color .2s ease}
.focusable.focused{transform:scale(1.055) translateY(-3px);box-shadow:0 0 0 3px #B4D2BD,0 20px 44px rgba(0,0,0,.62),0 0 28px rgba(180,210,189,.22);z-index:2}
.btn{display:inline-flex;align-items:center;gap:12px;height:68px;padding:0 34px;border-radius:34px;font-size:26px;font-weight:600;background:rgba(38,58,46,.88);color:#EDF3EC;border:1px solid rgba(180,210,189,.22);backdrop-filter:blur(16px)}
.btn.primary{background:#B4D2BD;color:#153B2A;border-color:#B4D2BD}
.btn.focused{transform:scale(1.05) translateY(-2px)}
.rows{height:calc(100% - 110px);overflow:hidden}.rows-inner{transition:transform .38s cubic-bezier(.22,1,.36,1);will-change:transform}
.row{margin-bottom:40px}.track{display:flex;gap:26px;transition:transform .36s cubic-bezier(.22,1,.36,1);padding:10px 4px;will-change:transform}
.card{flex:0 0 auto;width:220px;border-radius:20px;overflow:hidden;background:#15241B;border:1px solid rgba(180,210,189,.16);box-shadow:0 10px 26px rgba(0,0,0,.32)}
.card .art{width:220px;height:330px;background:#263A2E center/cover;transition:transform .36s cubic-bezier(.22,1,.36,1)}
.card.focused .art{transform:scale(1.03)}
.card.wide{width:400px}.card.wide .art{width:400px;height:225px}
.card .t{padding:12px 14px;font-size:21px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;background:linear-gradient(180deg,rgba(16,27,23,.72),rgba(16,27,23,.96))}
.prog{height:6px;background:#304437}.prog b{display:block;height:100%;background:#B4D2BD;transition:width .25s ease}
.chip{flex:0 0 auto;height:96px;min-width:200px;padding:0 30px;border-radius:24px;display:flex;align-items:center;justify-content:center;font-size:28px;font-weight:700;background:rgba(21,36,27,.88);border:1px solid rgba(180,210,189,.22);box-shadow:0 10px 24px rgba(0,0,0,.28)}
.chip small{font-size:18px;font-weight:500;color:#B7C9BD;margin-left:10px}
.filters{display:flex;gap:16px;margin-bottom:12px}.pill{height:52px;padding:0 26px;border-radius:26px;font-size:22px;font-weight:600;display:flex;align-items:center;background:rgba(21,36,27,.86);border:1px solid rgba(180,210,189,.22);backdrop-filter:blur(12px)}
.pill.on{background:#254D3C;color:#B4D2BD;border-color:#B4D2BD;box-shadow:0 6px 18px rgba(0,0,0,.3)}
.code{display:flex;gap:18px;margin:36px 0}.code span{width:110px;height:140px;border-radius:24px;background:#15241B;border:2px solid #B4D2BD;font-size:84px;font-weight:700;display:flex;align-items:center;justify-content:center;color:#B4D2BD}
.signin{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:1100px;padding:70px 80px;text-align:left}
.steps{font-size:26px;line-height:1.7;color:#B7C9BD}.steps b{color:#EDF3EC}
.detail{max-width:1080px;padding-top:8px}.detail p{font-size:24px;line-height:1.45;color:#B7C9BD;margin:14px 0 20px;max-height:105px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;text-shadow:0 2px 14px rgba(0,0,0,.65)}
.meta{display:flex;gap:14px;font-size:23px;color:#B7C9BD;margin-top:14px}.meta span{padding:6px 16px;border-radius:12px;background:rgba(37,77,60,.72);border:1px solid rgba(180,210,189,.16)}
.actions{display:flex;gap:20px}
.searchbox{height:88px;width:1000px;border-radius:44px;padding:0 40px;font-size:34px;display:flex;align-items:center;margin-bottom:24px}
.keys{display:grid;grid-template-columns:repeat(13,74px);gap:10px;margin-bottom:30px}.key{height:64px;border-radius:14px;background:#15241B;border:1px solid rgba(180,210,189,.22);display:flex;align-items:center;justify-content:center;font-size:26px}
.key.w2{grid-column:span 2}
#player{position:fixed;top:0;left:0;right:0;bottom:0;background:#000}#player video,#player object{width:100%;height:100%}
.osd{position:absolute;left:96px;right:96px;bottom:60px;padding:30px 40px;transition:opacity .32s cubic-bezier(.22,1,.36,1),transform .32s cubic-bezier(.22,1,.36,1)}.osd .bar{height:8px;border-radius:4px;background:#304437;margin:18px 0}.osd .bar b{display:block;height:100%;border-radius:4px;background:#B4D2BD}
.osd .row2{display:flex;justify-content:space-between;font-size:22px;color:#B7C9BD}
.osd.hide{opacity:0;transform:translateY(14px)}
#toast{position:fixed;right:60px;bottom:50px;padding:20px 30px;border-radius:18px;background:rgba(37,61,48,.94);border:1px solid rgba(180,210,189,.22);font-size:24px;opacity:0;transform:translateY(10px);transition:opacity .24s cubic-bezier(.22,1,.36,1),transform .24s cubic-bezier(.22,1,.36,1)}#toast.show{opacity:1;transform:translateY(0)}
.empty{font-size:26px;color:#B7C9BD;padding:20px 0}
@media (prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}.focusable.focused{transform:none}}
.chip{flex-direction:column;height:auto;min-width:150px;padding:18px 20px;gap:12px}.chip .cn{font-size:20px;font-weight:600;color:#B7C9BD}
.logo{display:inline-flex;align-items:center;justify-content:center;border-radius:18px;border:1px solid rgba(255,255,255,.18)}.logo.mono{background:#B4D2BD;color:#153B2A;font-weight:700;font-size:26px}
.plogo .logo{border-radius:30px}.plogo .logo.mono{font-size:46px}
.state{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:1000px;padding:60px 70px}.state p{font-size:26px;margin:20px 0 34px}
.buffer{position:absolute;left:50%;top:44%;transform:translate(-50%,-50%);padding:18px 32px;border-radius:18px;background:rgba(16,27,23,.85);font-size:26px;display:none}
.menu{position:absolute;right:60px;top:60px;bottom:220px;width:520px;padding:34px;overflow:hidden}.opt{height:60px;border-radius:16px;padding:0 22px;display:flex;align-items:center;font-size:24px;margin-bottom:8px}
.opt.on{background:#254D3C;color:#B4D2BD}.opt.focused{transform:none;box-shadow:inset 0 0 0 3px #B4D2BD}
.detail.row{margin-bottom:22px}
.ver-badge{font-size:20px;font-weight:600;padding:4px 14px;border-radius:14px;background:#15241B;color:#B7C9BD;border:1px solid rgba(180,210,189,.22)}
.btn.has-update{background:#254D3C;color:#B4D2BD;border-color:#B4D2BD}
.ota-banner{margin:0 0 22px;padding:18px 30px;display:flex;justify-content:space-between;align-items:center;font-size:24px;border-color:#B4D2BD;background:rgba(37,77,60,.88)}
.modal-backdrop{position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(10,18,14,.82);z-index:20;display:flex;align-items:center;justify-content:center}
.modal-card{width:1060px;padding:58px 68px}
.ota-status{font-size:26px;line-height:1.5;color:#B7C9BD;margin-top:24px;padding:20px 24px;border-radius:16px;background:#15241B;border:1px solid rgba(180,210,189,.22)}
.hero{max-width:920px;padding:14px 4px 20px;margin-bottom:24px;position:relative}
.hero-body{max-width:920px}
.hero-eyebrow{font-size:20px;font-weight:700;letter-spacing:1.6px;text-transform:uppercase;color:#B4D2BD;margin-bottom:8px;text-shadow:0 2px 12px rgba(0,0,0,.6)}
.hero-title{font-size:54px;font-weight:700;line-height:1.08;letter-spacing:-.6px;color:#EDF3EC;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-shadow:0 4px 24px rgba(0,0,0,.65)}
.hero .meta{margin-top:12px}
.hero-desc{max-width:820px;font-size:24px;line-height:1.45;color:#B7C9BD;margin:14px 0 22px;max-height:70px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;text-shadow:0 2px 14px rgba(0,0,0,.65)}
.ep-card .art{position:relative}
.ep-badge{position:absolute;top:12px;left:12px;padding:4px 12px;border-radius:10px;font-size:16px;font-weight:700;letter-spacing:.8px;text-transform:uppercase;background:#B4D2BD;color:#153B2A;box-shadow:0 4px 14px rgba(0,0,0,.45)}
.ep-badge.watched{background:#254D3C;color:#B4D2BD;border:1px solid #B4D2BD}
.ep-runtime{position:absolute;bottom:10px;right:12px;padding:3px 10px;border-radius:8px;font-size:16px;font-weight:600;background:rgba(16,27,23,.86);color:#B7C9BD}
.person-card{flex:0 0 auto;width:200px;padding:20px 16px;border-radius:20px;background:rgba(21,36,27,.88);border:1px solid rgba(180,210,189,.22);display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px;box-shadow:0 10px 26px rgba(0,0,0,.3)}
.person-avatar{width:104px;height:104px;border-radius:52px;background:#254D3C center/cover no-repeat;border:2px solid rgba(180,210,189,.22);display:flex;align-items:center;justify-content:center;font-size:32px;font-weight:700;color:#B4D2BD;margin-bottom:4px}
.p-name{font-size:21px;font-weight:600;color:#EDF3EC;width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.p-role{font-size:17px;color:#B7C9BD;width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.detail-credits{font-size:20px;color:#B7C9BD;margin:-6px 0 20px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-shadow:0 2px 10px rgba(0,0,0,.6)}.detail-credits b{color:#EDF3EC;font-weight:600}
.ep-info{padding:12px 16px 14px;background:linear-gradient(180deg,rgba(21,36,27,.86),rgba(16,27,23,.98))}
.ep-title{font-size:21px;font-weight:600;color:#EDF3EC;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:flex;align-items:center;gap:10px}
.ep-num{display:inline-flex;align-items:center;justify-content:center;padding:2px 10px;border-radius:8px;font-size:16px;font-weight:700;background:#254D3C;color:#B4D2BD;border:1px solid rgba(180,210,189,.22);flex:0 0 auto}
.ep-sub{font-size:17px;line-height:1.35;color:#B7C9BD;margin-top:5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ep-preview{max-width:1280px;padding:14px 22px;margin:2px 0 16px;border-radius:18px;background:rgba(21,36,27,.88);border:1px solid rgba(180,210,189,.22);backdrop-filter:blur(16px);box-shadow:0 12px 32px rgba(0,0,0,.32)}
.ep-prev-head{display:flex;align-items:center;gap:16px;margin-bottom:4px}
.ep-prev-tag{font-size:21px;font-weight:700;color:#B4D2BD}
.ep-prev-meta{font-size:18px;font-weight:600;color:#B7C9BD;padding:2px 12px;border-radius:10px;background:rgba(37,77,60,.65)}
.ep-prev-desc{font-size:20px;line-height:1.4;color:#EDF3EC;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.pill-sep{width:24px;flex:0 0 24px}
.card.rank-card{width:288px;display:flex;align-items:flex-end;background:transparent;border:none;box-shadow:none;overflow:visible;position:relative;padding-left:68px}
.card.rank-card.focused{transform:scale(1.055) translateY(-3px);box-shadow:none}
.rank-num{position:absolute;left:-4px;bottom:14px;width:88px;text-align:right;padding-right:8px;font-size:138px;font-weight:900;line-height:.82;letter-spacing:-7px;color:rgba(21,36,27,.92);-webkit-text-stroke:3px #B4D2BD;text-shadow:0 12px 28px rgba(0,0,0,.68);pointer-events:none;z-index:1;transition:transform .28s cubic-bezier(.22,1,.36,1),color .24s ease}
.card.rank-card.focused .rank-num{color:#B4D2BD;-webkit-text-stroke:2px #EDF3EC;transform:scale(1.06) translateX(-4px)}
.rank-poster{width:220px;border-radius:20px;overflow:hidden;background:#15241B;border:1px solid rgba(180,210,189,.18);box-shadow:0 12px 28px rgba(0,0,0,.38);position:relative;z-index:2;transition:box-shadow .24s cubic-bezier(.22,1,.36,1),border-color .2s ease}
.card.rank-card.focused .rank-poster{box-shadow:0 0 0 3px #B4D2BD,0 20px 44px rgba(0,0,0,.62),0 0 28px rgba(180,210,189,.22);border-color:#B4D2BD}
.rank-poster .art{position:relative}
.rank-badge{position:absolute;top:10px;right:10px;padding:3px 10px;border-radius:9px;font-size:14px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;background:rgba(16,27,23,.88);color:#B4D2BD;border:1px solid rgba(180,210,189,.28)}
.nextup-card .art{position:relative}
